package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Map;
import java.util.Set;

/**
 * Locality (canonical region) for pet owners. For a created owner the region is read straight off
 * the REGION prefix of its {@code customerCode} (see {@link AssignCustomerCode}), so the locality
 * shown on responses is exactly the region baked into the region-and-hash identity. When no such
 * code is present (e.g. legacy owners with no customer code) it falls back to resolving the region
 * from the owner's postcode first, using fixed inclusive postcode ranges: {@code NSW 2000-2099},
 * {@code VIC 3000-3099}, {@code QLD 4000-4099}; when the postcode is absent or falls in no known
 * range, it falls back to a fixed city-to-region table: {@code Sydney -> NSW},
 * {@code Melbourne -> VIC}, {@code Brisbane -> QLD}. Anything unresolved yields {@code UNKNOWN}.
 * Preferring the postcode returns the same region for known cities but disambiguates cities that
 * share a name. Derived purely from the owner's own state, so it carries no stored data and is
 * seed-independent. Used by the owner mapper to expose {@code locality} on responses.
 */
public final class Locality {

    /** City -> canonical region. Fixed, pinned reference data. */
    private static final Map<String, String> CITY_REGION = Map.of(
            "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");

    /** The canonical regions a customer code may carry, used to recognise its REGION prefix. */
    private static final Set<String> KNOWN_REGIONS = Set.of("NSW", "VIC", "QLD", "UNKNOWN");

    /** Region -> inclusive 4-digit postcode range {low, high}. Fixed, pinned reference data. */
    private static final Map<String, int[]> REGION_RANGES = Map.of(
            "NSW", new int[] {2000, 2099},
            "VIC", new int[] {3000, 3099},
            "QLD", new int[] {4000, 4099});

    private Locality() {
    }

    /**
     * The canonical region for an owner, read from the REGION prefix of its {@code customerCode}
     * when present and falling back to the postcode-then-city derivation otherwise. This is the
     * mapping the owner mapper uses so the exposed locality matches the region-and-hash identity.
     */
    public static String of(String customerCode, String postcode, String city) {
        String fromCode = fromCustomerCode(customerCode);
        return fromCode != null ? fromCode : of(postcode, city);
    }

    /**
     * The canonical region for the given owner, resolved from the postcode first and falling back
     * to the city when the postcode is absent or in no known range. Yields {@code UNKNOWN} when
     * neither resolves.
     */
    public static String of(String postcode, String city) {
        String byPostcode = fromPostcode(postcode);
        return byPostcode != null ? byPostcode : of(city);
    }

    /**
     * The canonical region for the given city, or {@code UNKNOWN} when the city is not in the
     * fixed table.
     */
    public static String of(String city) {
        return CITY_REGION.getOrDefault(city, "UNKNOWN");
    }

    /** The REGION prefix of a {@code <REGION>-<HASH8>} customer code, or {@code null} when the code
     *  is absent or does not carry a recognised region. */
    private static String fromCustomerCode(String customerCode) {
        if (customerCode == null) {
            return null;
        }
        int dash = customerCode.indexOf('-');
        if (dash <= 0) {
            return null;
        }
        String region = customerCode.substring(0, dash);
        return KNOWN_REGIONS.contains(region) ? region : null;
    }

    /** The region whose range contains the postcode, or {@code null} when absent or out of range. */
    private static String fromPostcode(String postcode) {
        if (postcode == null || !postcode.matches("[0-9]{4}")) {
            return null;
        }
        int value = Integer.parseInt(postcode);
        for (Map.Entry<String, int[]> entry : REGION_RANGES.entrySet()) {
            int[] range = entry.getValue();
            if (value >= range[0] && value <= range[1]) {
                return entry.getKey();
            }
        }
        return null;
    }
}
=== MembershipLevel ===
package org.springframework.samples.petclinic.rest.function.owner;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Numeric membership level for pet owners, from 1 to 4, derived from an owner's
 * {@link MembershipPoints}. The points are banded into a level: 1 for 0-1 points, 2 for 2-3 points,
 * 3 for 4-5 points and 4 for 6 or more points. Because a newly created owner earns no tenure points,
 * a new owner tops out at 5 points (email, unique name and a household of 3 or more), reaching level
 * 4 only once at least one fiscal year has elapsed. Used by the owner mapper to expose {@code membershipLevel}
 * on responses.
 *
 * <p>A new owner's level is additionally capped at creation time so it cannot exceed one above the
 * maximum level then held by its household members (see {@link CapMembershipLevel}); the ceiling is
 * stored on the owner as {@code membershipLevelCap}. {@link #of(Owner)} applies that ceiling to the
 * points-banded level. With no ceiling recorded (no existing household member, or a pre-existing
 * owner) the level is the points-banded value unchanged.
 */
public final class MembershipLevel {

    private MembershipLevel() {
    }

    /**
     * The membership level for the given points total: 1 for 0-1, 2 for 2-3, 3 for 4-5, 4 for 6 or
     * more.
     */
    public static int of(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }

    /**
     * The owner's effective membership level: the points-banded level ({@link #of(int)} over
     * {@link MembershipPoints}), lowered to the stored {@code membershipLevelCap} ceiling when one
     * was recorded at create time. With no ceiling the points-banded level is returned unchanged.
     */
    public static int of(Owner owner) {
        int level = of(MembershipPoints.of(owner.getNamesakeCount(), owner.getEmail(),
                owner.getHouseholdSize(), owner.getRegistrationDate()));
        Integer cap = owner.getMembershipLevelCap();
        return cap == null ? level : Math.min(level, cap);
    }
}
=== MembershipPoints ===
package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

/**
 * Points score behind a pet owner's membership. Every owner starts at 0 points; the score gains 2
 * when the owner has an email address (non-null, non-blank), a further 1 when its
 * {@code namesakeCount} is 0 (no existing owner shares its first and last name), a further 2 when
 * its {@code householdSize} is 3 or more, and a further 3 when at least one fiscal year has elapsed
 * since the owner's {@code registrationDate} (the fiscal year starting 1 July — see
 * {@link FiscalYear}), i.e. the owner registered in an earlier fiscal year than the current one.
 * Because a newly created owner's registration date is the current date, it shares the current
 * fiscal year, so a new owner never earns the tenure points. Derived purely from the owner's own
 * stored state ({@code namesakeCount} and {@code householdSize} are recorded at create time), so it
 * is seed-independent. Used by the owner mapper to expose {@code membershipPoints} on responses and,
 * via {@link MembershipLevel}, {@code membershipLevel}.
 */
public final class MembershipPoints {

    private MembershipPoints() {
    }

    /**
     * The membership points for the given namesake count, email, household size and registration
     * date: 0 to start, +2 when the email is present (non-null, non-blank), +1 when the namesake
     * count is exactly 0, +2 when the household size is 3 or more, +3 when at least one fiscal year
     * has elapsed since {@code registrationDate}.
     */
    public static int of(Integer namesakeCount, String email, Integer householdSize,
            LocalDate registrationDate) {
        int points = 0;
        boolean hasEmail = email != null && !email.isBlank();
        if (hasEmail) {
            points += 2;
        }
        boolean unique = namesakeCount != null && namesakeCount == 0;
        if (unique) {
            points += 1;
        }
        boolean largeHousehold = householdSize != null && householdSize >= 3;
        if (largeHousehold) {
            points += 2;
        }
        boolean tenured = registrationDate != null
                && FiscalYear.of(LocalDate.now()) - FiscalYear.of(registrationDate) >= 1;
        if (tenured) {
            points += 3;
        }
        return points;
    }
}
=== CapMembershipLevel ===
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Step of {@code POST /api/owners} that records the owner's membership-level ceiling: a new owner's
 * {@code membershipLevel} cannot exceed one above the current maximum {@code membershipLevel} among
 * its household members ({@link Household#id(String, String) same householdId}, i.e. same last name
 * and postcode). Runs after {@link CountHouseholdMembers} (so the household state is set) and before
 * {@link SaveOwner} (so the owner being created is not counted as its own household member). The
 * ceiling is {@code maxHouseholdMemberLevel + 1}, stored on the owner as {@code membershipLevelCap}
 * and applied by {@link MembershipLevel#of(Owner)} when the level is exposed. With no existing
 * household member no ceiling is recorded and no cap applies.
 */
public class CapMembershipLevel {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String householdId = Household.id(owner.getLastName(), owner.getPostcode());
        Integer maxLevel = null;
        for (Owner other : ownerRepository.findAll()) {
            if (householdId.equals(Household.id(other.getLastName(), other.getPostcode()))) {
                int level = MembershipLevel.of(other);
                if (maxLevel == null || level > maxLevel) {
                    maxLevel = level;
                }
            }
        }
        if (maxLevel != null) {
            owner.setMembershipLevelCap(maxLevel + 1);
        }
    }
}

